# This wCELO copy preserves the corrected ECO-USDT Step-4A validation rules.
# Only pool-specific filenames, the display title, and explanatory text change.
# It reads saved files locally and makes no Dune requests.
# ============================================================================
# AMM ADAPTATION -- wCELO ADDITIONAL POOL -- STEP 4A -- INTERNSHIP REPORT / WTEYE-STYLE VALIDATION
# ============================================================================
#
# OUR PURPOSE
# -----------
# We independently validate the candidate files generated by:
#
#   amm_adaptation_additional_pool_wcelo_step_3_internship_report_wteye_balance.R
#
# We do NOT search for new candidates in this step and we do NOT change any
# threshold. Instead, we go back to the unchanged Step-2 token-flow inputs and
# reconstruct every saved candidate from its original window, token, SCC, and
# swap identifiers.
#
# WHY WE NEED THIS CHECKPOINT
# ---------------------------
# Step 3 found structural balance candidates. Before interpreting or comparing
# them in the reduced-AMM comparison, we need to establish that:
#
# 1. every saved event_key refers to the intended original swaps;
# 2. every candidate is exactly an SCC-internal movement set from its recorded
#    source window;
# 3. the saved WTEYE-style ratio can be recomputed independently;
# 4. every saved candidate satisfies the documented < 10% rule;
# 5. token0/token1 flags in the labeled-swap files agree with the match files;
# 6. group IDs and summary counts can be reconstructed from the saved matches;
# 7. the Step-2 input fingerprints still match those recorded in Step 3.
#
# This is a validation step, not a new wash-trading classifier.
#
# BALANCE CONDITION WE RECOMPUTE
# ------------------------------
# For one token and one candidate SCC:
#
#   balance_i = received_i - sent_i
#
#   L1_balance = sum_i |balance_i|
#
#   V_total = sum of all token-movement amounts
#
#   ratio = L1_balance / (2 * V_total)
#
# The Step-3 candidate must satisfy:
#
#   ratio < 0.10
#
# We intentionally use a calculation written differently from Step 3: we build
# explicit received and sent totals address by address. Agreement therefore gives
# us an implementation cross-check rather than merely rereading the saved ratio.
#
# SCRIPT LOCATION
# ---------------
# D:/Downloads/Bachelor Thesis/Scripts/
# amm_adaptation_additional_pool_wcelo_step_4a_internship_report_validate_candidates.R
#
# REQUIRED INPUTS IN Data/cleaned
# -------------------------------
# Step-2 prepared inputs:
#   amm_adaptation_additional_pool_wcelo_input_suspicious_pool_token_flows.csv
#   amm_adaptation_additional_pool_wcelo_input_control_pool_token_flows.csv
#
# Step-3 WTEYE-style outputs:
#   amm_adaptation_additional_pool_wcelo_output_suspicious_pool_internship_report_wteye_token_matches.csv
#   amm_adaptation_additional_pool_wcelo_output_suspicious_pool_internship_report_wteye_swaps_labeled.csv
#   amm_adaptation_additional_pool_wcelo_output_control_pool_internship_report_wteye_token_matches.csv
#   amm_adaptation_additional_pool_wcelo_output_control_pool_internship_report_wteye_swaps_labeled.csv
#   amm_adaptation_additional_pool_wcelo_output_both_pools_internship_report_wteye_detection_summary.csv
#
# OUTPUTS
# -------
# 1. One row per token-level candidate validation:
#   amm_adaptation_additional_pool_wcelo_output_both_pools_internship_report_wteye_candidate_validation.csv
#
# 2. One validation summary row per sample:
#   amm_adaptation_additional_pool_wcelo_output_both_pools_internship_report_wteye_validation_summary.csv
#
# If a required consistency condition fails, the script stops before declaring
# validation PASS. We send the complete console output if that happens.
#
# HOW WE RUN IT
# -------------
# source("D:/Downloads/Bachelor Thesis/Scripts/amm_adaptation_additional_pool_wcelo_step_4a_internship_report_validate_candidates.R")

local({
  # ========================================================================
  # 1. WE SET OUR PATHS AND EXACT FILENAMES
  # ========================================================================
  base_dir <- "D:/Downloads/Bachelor Thesis"
  cleaned_dir <- file.path(base_dir, "Data", "cleaned")

  flow_files <- c(
    suspicious_pool = "amm_adaptation_additional_pool_wcelo_input_suspicious_pool_token_flows.csv",
    control_pool = "amm_adaptation_additional_pool_wcelo_input_control_pool_token_flows.csv"
  )

  match_files <- c(
    suspicious_pool =
      "amm_adaptation_additional_pool_wcelo_output_suspicious_pool_internship_report_wteye_token_matches.csv",
    control_pool =
      "amm_adaptation_additional_pool_wcelo_output_control_pool_internship_report_wteye_token_matches.csv"
  )

  labeled_files <- c(
    suspicious_pool =
      "amm_adaptation_additional_pool_wcelo_output_suspicious_pool_internship_report_wteye_swaps_labeled.csv",
    control_pool =
      "amm_adaptation_additional_pool_wcelo_output_control_pool_internship_report_wteye_swaps_labeled.csv"
  )

  detection_summary_file <-
    "amm_adaptation_additional_pool_wcelo_output_both_pools_internship_report_wteye_detection_summary.csv"

  validation_detail_file <-
    "amm_adaptation_additional_pool_wcelo_output_both_pools_internship_report_wteye_candidate_validation.csv"

  validation_summary_file <-
    "amm_adaptation_additional_pool_wcelo_output_both_pools_internship_report_wteye_validation_summary.csv"

  flow_paths <- file.path(cleaned_dir, unname(flow_files))
  match_paths <- file.path(cleaned_dir, unname(match_files))
  labeled_paths <- file.path(cleaned_dir, unname(labeled_files))
  detection_summary_path <- file.path(cleaned_dir, detection_summary_file)

  names(flow_paths) <- names(flow_files)
  names(match_paths) <- names(match_files)
  names(labeled_paths) <- names(labeled_files)

  required_paths <- c(
    flow_paths, match_paths, labeled_paths, detection_summary_path
  )

  cat("AMM ADAPTATION -- wCELO ADDITIONAL POOL -- STEP 4A -- INTERNSHIP REPORT / WTEYE-STYLE VALIDATION\n\n")
  cat("R version:", R.version.string, "\n")
  cat("Data folder:", cleaned_dir, "\n")

  if (!requireNamespace("igraph", quietly = TRUE)) {
    stop("Missing R package: igraph -- send the complete console output.",
         call. = FALSE)
  }

  if (!all(file.exists(required_paths))) {
    missing <- required_paths[!file.exists(required_paths)]
    stop(
      paste0(
        "A required Step-2 or Step-3 file is missing:\n",
        paste(missing, collapse = "\n")
      ),
      call. = FALSE
    )
  }

  # ========================================================================
  # 2. SMALL HELPERS FOR SAFE READING AND COMPARISON
  # ========================================================================
  read_all_text <- function(path) {
    utils::read.csv(
      path,
      colClasses = "character",
      check.names = FALSE,
      stringsAsFactors = FALSE,
      na.strings = ""
    )
  }

  to_integer_checked <- function(x, field) {
    y <- suppressWarnings(as.numeric(x))
    bad <- !is.finite(y) | y < 0 | y != floor(y) |
      y > .Machine$integer.max
    if (any(bad)) {
      stop(paste("Invalid integer field during validation:", field),
           call. = FALSE)
    }
    as.integer(y)
  }

  to_numeric_checked <- function(x, field, allow_zero = TRUE) {
    y <- suppressWarnings(as.numeric(x))
    bad <- !is.finite(y)
    if (allow_zero) bad <- bad | y < 0 else bad <- bad | y <= 0
    if (any(bad)) {
      stop(paste("Invalid numeric field during validation:", field),
           call. = FALSE)
    }
    y
  }

  to_logical_checked <- function(x, field) {
    if (is.logical(x)) return(x)
    y <- toupper(trimws(as.character(x)))
    if (any(!(y %in% c("TRUE", "FALSE")))) {
      stop(paste("Invalid logical field during validation:", field),
           call. = FALSE)
    }
    y == "TRUE"
  }

  close_enough <- function(a, b) {
    if (length(a) != length(b) || any(!is.finite(c(a, b)))) return(FALSE)
    tolerance <- 1e-11 * pmax(1, abs(a), abs(b))
    all(abs(a - b) <= tolerance)
  }

  parse_event_key <- function(key) {
    parts <- strsplit(key, ";", fixed = TRUE)[[1L]]
    ids <- suppressWarnings(as.integer(parts))
    if (!length(ids) || anyNA(ids) || any(ids <= 0L) ||
        anyDuplicated(ids) || !identical(ids, sort(ids))) {
      stop(paste("Invalid event_key:", key), call. = FALSE)
    }
    ids
  }

  split_group_ids <- function(x) {
    if (is.na(x) || !nzchar(x)) return(character())
    unique(strsplit(x, ";", fixed = TRUE)[[1L]])
  }

  normalize_id_set <- function(x) {
    # An unlabeled swap can be represented as NULL in our reconstructed list
    # but as an empty/NA CSV field when read back from disk. These all mean the
    # same mathematical set: no candidate group IDs. We normalize them before
    # comparing sets so that NULL and character(0) are not treated as different.
    if (is.null(x) || !length(x)) return(character())

    x <- as.character(x)
    x <- x[!is.na(x) & nzchar(x)]

    if (!length(x)) return(character())

    sort(unique(x))
  }

  same_set <- function(a, b) {
    identical(normalize_id_set(a), normalize_id_set(b))
  }

  # ========================================================================
  # 3. WE READ AND RECHECK THE STEP-2 TOKEN-FLOW INPUTS
  # ========================================================================
  read_flows <- function(path, sample_name) {
    x <- read_all_text(path)

    required <- c(
      "sample", "source_file", "source_row", "event_id", "swap_index",
      "row_id", "pool_address", "initiator_address", "transaction_hash",
      "block_number", "log_index", "token_slot", "direction", "seller", "buyer",
      "amount_raw", "scale_raw", "amount"
    )

    if (!nrow(x) || anyDuplicated(names(x)) ||
        !all(required %in% names(x)) ||
        anyNA(x[, required, drop = FALSE])) {
      stop(paste(sample_name, "has an invalid prepared input."),
           call. = FALSE)
    }

    if (any(x$sample != sample_name) ||
        length(unique(x$pool_address)) != 1L ||
        any(!(x$token_slot %in% c("token0", "token1")))) {
      stop(paste(sample_name, "has inconsistent prepared identifiers."),
           call. = FALSE)
    }

    for (field in c(
      "source_row", "swap_index", "row_id", "block_number", "log_index"
    )) {
      x[[field]] <- to_integer_checked(x[[field]], field)
    }

    x$amount <- to_numeric_checked(x$amount, "amount", allow_zero = FALSE)

    if (any(x$row_id != x$swap_index)) {
      stop("row_id and swap_index differ in a prepared input.",
           call. = FALSE)
    }

    if (anyDuplicated(paste(x$event_id, x$token_slot, sep = "|"))) {
      stop("A prepared event/token row is repeated.", call. = FALSE)
    }

    x <- x[order(x$swap_index, x$token_slot), , drop = FALSE]
    rownames(x) <- NULL

    a <- x[x$token_slot == "token0", , drop = FALSE]
    b <- x[x$token_slot == "token1", , drop = FALSE]

    common <- c(
      "source_row", "event_id", "swap_index", "row_id",
      "pool_address", "initiator_address", "transaction_hash",
      "block_number", "log_index"
    )

    aa <- a[, common, drop = FALSE]
    bb <- b[, common, drop = FALSE]
    rownames(aa) <- NULL
    rownames(bb) <- NULL

    if (!identical(aa, bb) ||
        !identical(a$swap_index, seq_len(nrow(a)))) {
      stop("Prepared token0/token1 swap mappings disagree.",
           call. = FALSE)
    }

    x
  }

  flows <- lapply(names(flow_paths), function(sample_name) {
    read_flows(flow_paths[[sample_name]], sample_name)
  })
  names(flows) <- names(flow_paths)

  for (sample_name in names(flows)) {
    cat(
      "Prepared rows rechecked:",
      sample_name,
      nrow(flows[[sample_name]]),
      "\n"
    )
  }

  # ========================================================================
  # 4. WE READ THE STEP-3 OUTPUTS
  # ========================================================================
  detection_summary <- read_all_text(detection_summary_path)

  if (!all(c(
    "sample", "prepared_input_md5", "margin", "max_swaps",
    "max_block_span", "candidate_groups", "token_matches",
    "candidate_swap_events", "candidate_transactions",
    "candidate_initiators", "both_token_candidate_swaps",
    "token0_candidate_swaps", "token1_candidate_swaps",
    "balance_method", "scc_evaluation", "candidate_rule"
  ) %in% names(detection_summary))) {
    stop("The Step-3 detection summary has unexpected columns.",
         call. = FALSE)
  }

  if (!same_set(detection_summary$sample, names(flow_files))) {
    stop("The Step-3 detection summary does not contain exactly both samples.",
         call. = FALSE)
  }

  # We validate that the Step-2 inputs are exactly the files recorded by Step 3.
  for (sample_name in names(flow_paths)) {
    row <- detection_summary[
      detection_summary$sample == sample_name,
      ,
      drop = FALSE
    ]

    actual_md5 <- unname(tools::md5sum(flow_paths[[sample_name]]))

    if (nrow(row) != 1L ||
        row$prepared_input_md5 != actual_md5) {
      stop(
        paste(
          sample_name,
          "prepared-input MD5 no longer matches the Step-3 record."
        ),
        call. = FALSE
      )
    }
  }

  cat("PASS: Step-2 input fingerprints match the Step-3 records.\n")

  # ========================================================================
  # 5. OUR INDEPENDENT BALANCE CALCULATION
  # ========================================================================
  # Unlike Step 3's grouped tapply() implementation, this calculation loops over
  # the address set and separately sums received and sent amounts.
  independent_metrics <- function(movements, pool_address) {
    addresses <- sort(unique(c(
      movements$seller,
      movements$buyer
    )))

    received <- vapply(addresses, function(address) {
      sum(movements$amount[movements$buyer == address])
    }, numeric(1))

    sent <- vapply(addresses, function(address) {
      sum(movements$amount[movements$seller == address])
    }, numeric(1))

    balances <- received - sent
    names(balances) <- addresses

    total_volume <- sum(movements$amount)
    l1_balance <- sum(abs(balances))
    ratio <- l1_balance / (2 * total_volume)

    pool_abs <- if (pool_address %in% addresses) {
      abs(balances[[pool_address]])
    } else {
      NA_real_
    }

    trader_l1 <- sum(
      abs(balances[addresses != pool_address])
    )

    pool_fraction <- if (l1_balance > 0 && is.finite(pool_abs)) {
      pool_abs / l1_balance
    } else if (l1_balance == 0) {
      0
    } else {
      NA_real_
    }

    list(
      addresses = addresses,
      balances = balances,
      total_volume = total_volume,
      l1_balance = l1_balance,
      ratio = ratio,
      pool_abs = pool_abs,
      trader_l1 = trader_l1,
      pool_fraction = pool_fraction,
      conservation_error = abs(sum(balances))
    )
  }

  # ========================================================================
  # 6. WE RECONSTRUCT SCCs FROM A RECORDED SOURCE WINDOW
  # ========================================================================
  scc_sequences <- function(movements) {
    if (nrow(movements) < 2L) return(list())

    graph <- igraph::graph_from_data_frame(
      movements[, c("seller", "buyer"), drop = FALSE],
      directed = TRUE
    )

    membership <- igraph::components(
      graph,
      mode = "strong"
    )$membership

    vertices <- igraph::vertex_attr(graph, "name")
    vertex_groups <- split(vertices, membership)

    selected <- list()

    for (group in vertex_groups) {
      if (length(group) < 2L) next

      keep <-
        movements$seller %in% group &
        movements$buyer %in% group

      if (sum(keep) < 2L) next

      component <- movements[keep, , drop = FALSE]
      component <- component[
        order(component$swap_index, component$log_index),
        ,
        drop = FALSE
      ]
      rownames(component) <- NULL

      selected[[length(selected) + 1L]] <- component
    }

    selected
  }

  # ========================================================================
  # 7. WE VALIDATE EVERY SAVED TOKEN-LEVEL CANDIDATE
  # ========================================================================
  all_detail <- list()
  all_summary <- list()

  for (sample_name in names(flow_files)) {
    cat("\nValidating:", sample_name, "\n")

    x <- flows[[sample_name]]
    pool_address <- unique(x$pool_address)

    matches <- read_all_text(match_paths[[sample_name]])
    labeled <- read_all_text(labeled_paths[[sample_name]])

    required_match_columns <- c(
      "candidate_group_id", "token_slot", "event_key",
      "n_swap_events", "n_addresses", "n_initiators",
      "first_block", "last_block", "block_span",
      "source_window_start", "source_window_end",
      "contiguous_in_sample",
      "total_volume_scaled", "l1_balance_scaled",
      "wteye_balance_ratio", "pool_abs_balance_scaled",
      "trader_l1_balance_scaled", "pool_fraction_of_l1",
      "conservation_error_scaled", "margin",
      "margin_operator", "evaluation_mode", "classification"
    )

    if (!all(required_match_columns %in% names(matches))) {
      stop(paste(sample_name, "match report has unexpected columns."),
           call. = FALSE)
    }

    # Our current samples both contain matches. This reader also supports a later
    # zero-match sample if the CSV has the expected headings.
    if (nrow(matches)) {
      for (field in c(
        "n_swap_events", "n_addresses", "n_initiators",
        "first_block", "last_block", "block_span",
        "source_window_start", "source_window_end"
      )) {
        matches[[field]] <- to_integer_checked(
          matches[[field]], field
        )
      }

      for (field in c(
        "total_volume_scaled", "l1_balance_scaled",
        "wteye_balance_ratio", "pool_abs_balance_scaled",
        "trader_l1_balance_scaled", "pool_fraction_of_l1",
        "conservation_error_scaled", "margin"
      )) {
        matches[[field]] <- to_numeric_checked(
          matches[[field]], field, allow_zero = TRUE
        )
      }

      matches$contiguous_in_sample <- to_logical_checked(
        matches$contiguous_in_sample,
        "contiguous_in_sample"
      )
    }

    # We convert the labeled file's fields needed for validation.
    required_labeled_columns <- c(
      "source_row", "swap_index", "event_id", "pool_address",
      "initiator_address", "transaction_hash",
      "block_number", "log_index",
      "candidate_token0", "candidate_token1",
      "candidate_group_ids", "structural_candidate",
      "classification", "sample"
    )

    if (!all(required_labeled_columns %in% names(labeled))) {
      stop(paste(sample_name, "labeled-swap report has unexpected columns."),
           call. = FALSE)
    }

    for (field in c(
      "source_row", "swap_index", "block_number", "log_index"
    )) {
      labeled[[field]] <- to_integer_checked(
        labeled[[field]], field
      )
    }

    for (field in c(
      "candidate_token0", "candidate_token1",
      "structural_candidate"
    )) {
      labeled[[field]] <- to_logical_checked(
        labeled[[field]], field
      )
    }

    # token0 metadata from the prepared input is our independent swap reference.
    reference_swaps <- x[
      x$token_slot == "token0",
      c(
        "source_row", "swap_index", "event_id", "pool_address",
        "initiator_address", "transaction_hash",
        "block_number", "log_index"
      ),
      drop = FALSE
    ]
    rownames(reference_swaps) <- NULL

    labeled_reference <- labeled[, names(reference_swaps), drop = FALSE]
    rownames(labeled_reference) <- NULL

    if (!identical(reference_swaps, labeled_reference)) {
      stop(
        paste(
          sample_name,
          "labeled swap identifiers no longer match Step-2 input."
        ),
        call. = FALSE
      )
    }

    cat("  PASS: labeled swap identifiers match Step-2 input.\n")

    detail_rows <- list()

    if (nrow(matches)) {
      if (anyDuplicated(paste(
        matches$token_slot,
        matches$event_key,
        sep = "|"
      ))) {
        stop(
          paste(sample_name, "contains repeated token/event candidate rows."),
          call. = FALSE
        )
      }

      for (j in seq_len(nrow(matches))) {
        m <- matches[j, , drop = FALSE]

        ids <- parse_event_key(m$event_key)
        slot <- m$token_slot

        if (!(slot %in% c("token0", "token1"))) {
          stop("A candidate has an invalid token_slot.", call. = FALSE)
        }

        token_table <- x[x$token_slot == slot, , drop = FALSE]
        rownames(token_table) <- NULL

        first <- m$source_window_start
        last <- m$source_window_end

        summary_row <- detection_summary[
          detection_summary$sample == sample_name,
          ,
          drop = FALSE
        ]

        max_swaps <- as.integer(summary_row$max_swaps)
        max_block_span <- as.integer(summary_row$max_block_span)
        recorded_margin <- as.numeric(summary_row$margin)

        if (first < 1L || last > nrow(token_table) ||
            first >= last ||
            (last - first + 1L) > max_swaps) {
          stop(
            paste(
              sample_name,
              m$candidate_group_id,
              slot,
              "has an invalid recorded source window."
            ),
            call. = FALSE
          )
        }

        window <- token_table[first:last, , drop = FALSE]

        if (
          max(window$block_number) -
          min(window$block_number) >
          max_block_span
        ) {
          stop(
            paste(
              sample_name,
              m$candidate_group_id,
              slot,
              "exceeds the recorded maximum block span."
            ),
            call. = FALSE
          )
        }

        if (!all(ids %in% window$swap_index)) {
          stop(
            paste(
              sample_name,
              m$candidate_group_id,
              slot,
              "contains an event outside its recorded window."
            ),
            call. = FALSE
          )
        }

        # We reconstruct every nontrivial SCC in the source window and require
        # exactly one component whose internal movement IDs equal event_key.
        components <- scc_sequences(window)

        exact_component <- which(vapply(
          components,
          function(component) {
            identical(component$swap_index, ids)
          },
          logical(1)
        ))

        if (length(exact_component) != 1L) {
          stop(
            paste(
              sample_name,
              m$candidate_group_id,
              slot,
              "does not reconstruct as exactly one recorded SCC movement set."
            ),
            call. = FALSE
          )
        }

        component <- components[[exact_component]]
        metrics <- independent_metrics(
          component,
          pool_address
        )

        # A second direct graph check confirms that the candidate's internal
        # movements themselves are strongly connected.
        candidate_graph <- igraph::graph_from_data_frame(
          component[, c("seller", "buyer"), drop = FALSE],
          directed = TRUE
        )
        strongly_connected <-
          igraph::components(candidate_graph, mode = "strong")$no == 1L

        expected_contiguous <-
          nrow(component) ==
          max(component$swap_index) -
          min(component$swap_index) + 1L

        metadata_ok <-
          m$n_swap_events == nrow(component) &&
          m$n_addresses == length(metrics$addresses) &&
          m$n_initiators ==
            length(unique(component$initiator_address)) &&
          m$first_block == min(component$block_number) &&
          m$last_block == max(component$block_number) &&
          m$block_span ==
            max(component$block_number) -
            min(component$block_number) &&
          identical(
            as.logical(m$contiguous_in_sample),
            as.logical(expected_contiguous)
          )

        # pool_fraction_of_l1 is a descriptive derived field; it is not part of
        # the WTEYE balance equation or candidate rule. Dividing two small,
        # independently rounded balance quantities can magnify insignificant
        # summation-order differences. We therefore report fraction agreement
        # separately. Candidate validation relies on the independently checked
        # numerator, denominator, WTEYE ratio, and threshold decision.
        balance_zero_tolerance <-
          1e-12 * max(
            1,
            m$total_volume_scaled,
            metrics$total_volume
          )

        pool_fraction_comparable <- !(
          m$l1_balance_scaled <= balance_zero_tolerance &&
          metrics$l1_balance <= balance_zero_tolerance
        )

        pool_fraction_agrees <-
          !pool_fraction_comparable ||
          close_enough(
            m$pool_fraction_of_l1,
            metrics$pool_fraction
          )

        pool_fraction_in_range <-
          m$pool_fraction_of_l1 >= 0 &&
          m$pool_fraction_of_l1 <= 1 &&
          metrics$pool_fraction >= 0 &&
          metrics$pool_fraction <= 1

        numeric_ok <-
          close_enough(
            m$total_volume_scaled,
            metrics$total_volume
          ) &&
          close_enough(
            m$l1_balance_scaled,
            metrics$l1_balance
          ) &&
          close_enough(
            m$wteye_balance_ratio,
            metrics$ratio
          ) &&
          close_enough(
            m$pool_abs_balance_scaled,
            metrics$pool_abs
          ) &&
          close_enough(
            m$trader_l1_balance_scaled,
            metrics$trader_l1
          ) &&
          close_enough(
            m$conservation_error_scaled,
            metrics$conservation_error
          )

        rule_ok <-
          m$margin_operator == "<" &&
          close_enough(m$margin, recorded_margin) &&
          metrics$ratio < recorded_margin &&
          m$evaluation_mode ==
            "WHOLE_SCC_INTERNAL_MOVEMENTS_NO_PREFIX_TRUNCATION" &&
          m$classification ==
            "INTERNSHIP_REPORT_WTEYE_BALANCE_CANDIDATE"

        conservation_ok <-
          metrics$conservation_error <=
          1e-11 * max(1, metrics$total_volume)

        row_pass <-
          strongly_connected &&
          metadata_ok &&
          numeric_ok &&
          pool_fraction_in_range &&
          rule_ok &&
          conservation_ok

        detail_rows[[length(detail_rows) + 1L]] <- data.frame(
          sample = sample_name,
          candidate_group_id = m$candidate_group_id,
          token_slot = slot,
          event_key = m$event_key,
          source_window_start = first,
          source_window_end = last,
          reconstructed_as_exact_scc = length(exact_component) == 1L,
          strongly_connected = strongly_connected,
          metadata_agrees = metadata_ok,
          saved_total_volume_scaled = m$total_volume_scaled,
          recomputed_total_volume_scaled = metrics$total_volume,
          saved_l1_balance_scaled = m$l1_balance_scaled,
          recomputed_l1_balance_scaled = metrics$l1_balance,
          saved_wteye_balance_ratio = m$wteye_balance_ratio,
          recomputed_wteye_balance_ratio = metrics$ratio,
          absolute_ratio_difference =
            abs(m$wteye_balance_ratio - metrics$ratio),
          ratio_below_margin = metrics$ratio < recorded_margin,
          pool_fraction_comparable = pool_fraction_comparable,
          pool_fraction_values_agree = pool_fraction_agrees,
          pool_fraction_values_in_range = pool_fraction_in_range,
          numeric_values_agree = numeric_ok,
          conservation_check = conservation_ok,
          candidate_validation = if (row_pass) "PASS" else "FAIL",
          stringsAsFactors = FALSE
        )

        if (j %% 1000L == 0L || j == nrow(matches)) {
          cat(
            "  Candidate validations completed:",
            j,
            "of",
            nrow(matches),
            "\n"
          )
        }
      }
    }

    detail <- if (length(detail_rows)) {
      do.call(rbind, detail_rows)
    } else {
      data.frame(
        sample = character(),
        candidate_group_id = character(),
        token_slot = character(),
        event_key = character(),
        source_window_start = integer(),
        source_window_end = integer(),
        reconstructed_as_exact_scc = logical(),
        strongly_connected = logical(),
        metadata_agrees = logical(),
        saved_total_volume_scaled = numeric(),
        recomputed_total_volume_scaled = numeric(),
        saved_l1_balance_scaled = numeric(),
        recomputed_l1_balance_scaled = numeric(),
        saved_wteye_balance_ratio = numeric(),
        recomputed_wteye_balance_ratio = numeric(),
        absolute_ratio_difference = numeric(),
          ratio_below_margin = logical(),
          pool_fraction_comparable = logical(),
          pool_fraction_values_agree = logical(),
          pool_fraction_values_in_range = logical(),
          numeric_values_agree = logical(),
        conservation_check = logical(),
        candidate_validation = character(),
        stringsAsFactors = FALSE
      )
    }

    # ======================================================================
    # 8. WE RECONSTRUCT THE LABELED-SWAP FLAGS FROM THE MATCH REPORT
    # ======================================================================
    expected_token0 <- rep(FALSE, nrow(reference_swaps))
    expected_token1 <- rep(FALSE, nrow(reference_swaps))
    expected_group_ids <- vector("list", nrow(reference_swaps))

    if (nrow(matches)) {
      for (j in seq_len(nrow(matches))) {
        ids <- parse_event_key(matches$event_key[j])
        selected <- reference_swaps$swap_index %in% ids

        if (matches$token_slot[j] == "token0") {
          expected_token0[selected] <- TRUE
        } else {
          expected_token1[selected] <- TRUE
        }

        gid <- matches$candidate_group_id[j]

        for (position in which(selected)) {
          expected_group_ids[[position]] <- unique(c(
            expected_group_ids[[position]],
            gid
          ))
        }
      }
    }

    flags_ok <-
      identical(expected_token0, labeled$candidate_token0) &&
      identical(expected_token1, labeled$candidate_token1) &&
      identical(
        expected_token0 | expected_token1,
        labeled$structural_candidate
      )

    group_ids_ok <- TRUE

    for (i in seq_len(nrow(labeled))) {
      saved_ids <- split_group_ids(labeled$candidate_group_ids[i])
      expected_ids <- expected_group_ids[[i]]

      if (!same_set(saved_ids, expected_ids)) {
        group_ids_ok <- FALSE
        break
      }
    }

    expected_classification <- ifelse(
      expected_token0 | expected_token1,
      "INTERNSHIP_REPORT_WTEYE_BALANCE_CANDIDATE",
      "NO_MATCH_UNDER_CURRENT_SETTINGS"
    )

    classification_ok <- identical(
      expected_classification,
      labeled$classification
    )

    cat(
      "  ",
      if (flags_ok) "PASS" else "FAIL",
      ": token candidate flags reconstruct from match rows.\n",
      sep = ""
    )
    cat(
      "  ",
      if (group_ids_ok) "PASS" else "FAIL",
      ": candidate group IDs reconstruct from match rows.\n",
      sep = ""
    )
    cat(
      "  ",
      if (classification_ok) "PASS" else "FAIL",
      ": swap classifications reconstruct from candidate flags.\n",
      sep = ""
    )

    # ======================================================================
    # 9. WE RECOMPUTE THE SUMMARY COUNTS
    # ======================================================================
    step3_summary <- detection_summary[
      detection_summary$sample == sample_name,
      ,
      drop = FALSE
    ]

    selected <- expected_token0 | expected_token1

    recomputed_candidate_groups <-
      length(unique(matches$candidate_group_id))

    recomputed_token_matches <- nrow(matches)

    recomputed_candidate_swap_events <- sum(selected)

    recomputed_candidate_transactions <- length(unique(
      reference_swaps$transaction_hash[selected]
    ))

    recomputed_candidate_initiators <- length(unique(
      reference_swaps$initiator_address[selected]
    ))

    recomputed_both_token <- sum(
      expected_token0 & expected_token1
    )

    recomputed_token0 <- sum(expected_token0)
    recomputed_token1 <- sum(expected_token1)

    counts_ok <-
      as.integer(step3_summary$candidate_groups) ==
        recomputed_candidate_groups &&
      as.integer(step3_summary$token_matches) ==
        recomputed_token_matches &&
      as.integer(step3_summary$candidate_swap_events) ==
        recomputed_candidate_swap_events &&
      as.integer(step3_summary$candidate_transactions) ==
        recomputed_candidate_transactions &&
      as.integer(step3_summary$candidate_initiators) ==
        recomputed_candidate_initiators &&
      as.integer(step3_summary$both_token_candidate_swaps) ==
        recomputed_both_token &&
      as.integer(step3_summary$token0_candidate_swaps) ==
        recomputed_token0 &&
      as.integer(step3_summary$token1_candidate_swaps) ==
        recomputed_token1

    detail_ok <-
      !nrow(detail) ||
      all(detail$candidate_validation == "PASS")

    sample_pass <-
      detail_ok &&
      flags_ok &&
      group_ids_ok &&
      classification_ok &&
      counts_ok

    cat(
      "  ",
      if (detail_ok) "PASS" else "FAIL",
      ": every token-level candidate independently recomputed.\n",
      sep = ""
    )
    cat(
      "  ",
      if (counts_ok) "PASS" else "FAIL",
      ": Step-3 summary counts independently reconstructed.\n",
      sep = ""
    )

    all_detail[[sample_name]] <- detail

    all_summary[[sample_name]] <- data.frame(
      sample = sample_name,
      token_match_rows_checked = nrow(matches),
      candidate_groups_recomputed = recomputed_candidate_groups,
      candidate_swap_events_recomputed =
        recomputed_candidate_swap_events,
      candidate_transactions_recomputed =
        recomputed_candidate_transactions,
      candidate_initiators_recomputed =
        recomputed_candidate_initiators,
      both_token_candidate_swaps_recomputed =
        recomputed_both_token,
      token0_candidate_swaps_recomputed =
        recomputed_token0,
      token1_candidate_swaps_recomputed =
        recomputed_token1,
      pool_fraction_diagnostics_not_comparable =
        sum(!detail$pool_fraction_comparable),
      pool_fraction_diagnostics_differ =
        sum(
          detail$pool_fraction_comparable &
          !detail$pool_fraction_values_agree
        ),
      prepared_input_md5_matches = TRUE,
      labeled_identifiers_match_prepared = TRUE,
      token_flags_match = flags_ok,
      candidate_group_ids_match = group_ids_ok,
      classifications_match = classification_ok,
      summary_counts_match = counts_ok,
      all_candidate_recalculations_pass = detail_ok,
      overall_validation = if (sample_pass) "PASS" else "FAIL",
      stringsAsFactors = FALSE
    )
  }

  # ========================================================================
  # 10. WE SAVE THE VALIDATION REPORTS ONLY AFTER BOTH SAMPLES FINISH
  # ========================================================================
  detail_table <- do.call(rbind, all_detail)
  rownames(detail_table) <- NULL

  summary_table <- do.call(rbind, all_summary)
  rownames(summary_table) <- NULL

  if (!all(summary_table$overall_validation == "PASS")) {
    stop(
      "STEP 4A VALIDATION FAILED. No PASS conclusion will be written. Send the complete console output.",
      call. = FALSE
    )
  }

  # Recheck the input fingerprints immediately before writing our validation
  # reports so a changing input cannot silently pass the earlier check.
  for (sample_name in names(flow_paths)) {
    step3_row <- detection_summary[
      detection_summary$sample == sample_name,
      ,
      drop = FALSE
    ]

    if (
      unname(tools::md5sum(flow_paths[[sample_name]])) !=
      step3_row$prepared_input_md5
    ) {
      stop(
        "A prepared input changed during Step 4. Validation reports were not written.",
        call. = FALSE
      )
    }
  }

  write_report <- function(table, filename) {
    table_for_disk <- table

    for (field in names(table_for_disk)) {
      if (is.double(table_for_disk[[field]])) {
        table_for_disk[[field]] <-
          sprintf("%.17g", table_for_disk[[field]])
      }
    }

    path <- file.path(cleaned_dir, filename)

    if (file.exists(path)) {
      cat("Refreshing our generated validation file:", filename, "\n")
    }

    utils::write.csv(
      table_for_disk,
      path,
      row.names = FALSE,
      na = "",
      fileEncoding = "UTF-8"
    )

    cat("Saved:", path, "\n")
  }

  write_report(
    detail_table,
    validation_detail_file
  )

  write_report(
    summary_table,
    validation_summary_file
  )

  cat("\nSTEP 4A COMPLETE: WTEYE-style candidate validation PASS.\n")
  cat("Every saved candidate reconstructed from its recorded Step-2 source window and SCC.\n")
  cat("Every saved balance ratio independently recomputed and remained below the recorded margin.\n")
  cat("Swap flags, group IDs, classifications, and summary counts all reconstructed successfully.\n")
  cat("No candidate labels were changed by this validation step.\n")
  cat("Send the complete console output and both generated validation CSVs for review.\n")
  cat("Next step: Step 4B reviews the validated candidates; Step 5 applies the same filter variants as ECO-USDT.\n")
})
